// Convert a whole number from 1 to 3999 to a Roman numeral.
const VALUES = [
	[1000, "M"],
	[900, "CM"],
	[500, "D"],
	[400, "CD"],
	[100, "C"],
	[90, "XC"],
	[50, "L"],
	[40, "XL"],
	[10, "X"],
	[9, "IX"],
	[5, "V"],
	[4, "IV"],
	[1, "I"],
];

export function toRoman(n) {
	if (!Number.isInteger(n) || n < 1 || n > 3999) {
		throw new RangeError(`n must be an integer between 1 and 3999, got ${n}`);
	}
	let result = "";
	let remaining = n;
	for (const [value, symbol] of VALUES) {
		while (remaining >= value) {
			result += symbol;
			remaining -= value;
		}
	}
	return result;
}

